const items = Array.isArray($input.first().json) ? $input.first().json : [];
console.log(`[Moderation] Checking ${items.length} items`);
if (!items.length) return [];

function moderate(item) {
  const title = (item.title_ar || '').toLowerCase();
  const issues = [];

  // Trailers / promos
  if (/trailer|teaser|promo|preview|إعلان|بروموشن|clip/.test(title)) {
    issues.push('trailer_or_promo');
  }

  // Too short for films
  if (item.type === 'film' && item.duration_sec && item.duration_sec < 2700) {
    issues.push('too_short_for_film'); // < 45 min
  }

  // Suspicious titles
  if (/\d{4,}/.test(title) && title.length < 10) issues.push('suspicious_title');
  if (/test|demo|upload|sample/.test(title)) issues.push('test_content');

  // No yt_id
  if (!item.yt_id || item.yt_id.length !== 11) issues.push('invalid_yt_id');

  // Spammy patterns
  if (/http|www\.|bit\.ly|youtu\.be/.test(title)) issues.push('url_in_title');
  if ((title.match(/!/g) || []).length >= 3) issues.push('spam_punctuation');

  return { id: item.id, title: item.title_ar, issues, should_hide: issues.length > 0 };
}

return items.map(item => ({ json: moderate(item) }));

const items = $input.all();
const hidden = items.filter(i => !i.json.issues?.length && i.json.statusCode).length;
console.log(`[Moderation] ${hidden} items hidden`);
return [{ json: { hidden, run_at: new Date().toISOString() } }];
